  1066→// CreateBlobFromContent creates a blob object from in-memory content.
  1067→// Exported for use by strategy package (session_test.go)
  1068→func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
  1069→	obj := repo.Storer.NewEncodedObject()
  1070→	obj.SetType(plumbing.BlobObject)
  1071→	obj.SetSize(int64(len(content)))
  1072→
  1073→	writer, err := obj.Writer()
  1074→	if err != nil {
  1075→		return plumbing.ZeroHash, fmt.Errorf("failed to get object writer: %w", err)
  1076→	}
  1077→
  1078→	_, err = writer.Write(content)
  1079→	if err != nil {
  1080→		_ = writer.Close()
  1081→		return plumbing.ZeroHash, fmt.Errorf("failed to write blob content: %w", err)
  1082→	}
  1083→	if err := writer.Close(); err != nil {
  1084→		return plumbing.ZeroHash, fmt.Errorf("failed to close blob writer: %w", err)
  1085→	}
  1086→
  1087→	hash, err := repo.Storer.SetEncodedObject(obj)
  1088→	if err != nil {
  1089→		return plumbing.ZeroHash, fmt.Errorf("failed to store blob object: %w", err)
  1090→	}
  1091→	return hash, nil
  1092→}
  1093→
  1094→// copyMetadataDir copies all files from a directory to the checkpoint path.
  1095→// Used to include additional metadata files like task checkpoints, subagent transcripts, etc.
  1096→func (s *GitStore) copyMetadataDir(metadataDir, basePath string, entries map[string]object.TreeEntry) error {
  1097→	err := filepath.Walk(metadataDir, func(path string, info os.FileInfo, err error) error {
  1098→		if err != nil {
  1099→			return err
  1100→		}
  1101→		if info.IsDir() {
  1102→			return nil
  1103→		}
  1104→
  1105→		// Skip symlinks to prevent reading files outside the metadata directory.
  1106→		// A symlink could point to sensitive files (e.g., /etc/passwd) which would
  1107→		// then be captured in the checkpoint and stored in git history.
  1108→		if info.Mode()&os.ModeSymlink != 0 {
  1109→			return nil
  1110→		}
  1111→
  1112→		// Get relative path within metadata dir
  1113→		relPath, err := filepath.Rel(metadataDir, path)
  1114→		if err != nil {
  1115→			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
  1116→		}
  1117→
  1118→		// Prevent path traversal via symlinks pointing outside the metadata dir
  1119→		if strings.HasPrefix(relPath, "..") {
  1120→			return fmt.Errorf("path traversal detected: %s", relPath)
  1121→		}
  1122→
  1123→		// Create blob from file with secrets redaction
  1124→		blobHash, mode, err := createRedactedBlobFromFile(s.repo, path, relPath)
  1125→		if err != nil {
  1126→			return fmt.Errorf("failed to create blob for %s: %w", path, err)
  1127→		}
  1128→
  1129→		// Store at checkpoint path
  1130→		fullPath := basePath + relPath
  1131→		entries[fullPath] = object.TreeEntry{
  1132→			Name: fullPath,
  1133→			Mode: mode,
  1134→			Hash: blobHash,
  1135→		}
  1136→
  1137→		return nil
  1138→	})
  1139→	if err != nil {
  1140→		return fmt.Errorf("failed to walk metadata directory: %w", err)
  1141→	}
  1142→	return nil
  1143→}
  1144→
  1145→// createRedactedBlobFromFile reads a file, applies secrets redaction, and creates a git blob.
  1146→// JSONL files get JSONL-aware redaction; all other files get plain string redaction.
  1147→func createRedactedBlobFromFile(repo *git.Repository, filePath, treePath string) (plumbing.Hash, filemode.FileMode, error) {
  1148→	info, err := os.Stat(filePath)
  1149→	if err != nil {
  1150→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to stat file: %w", err)
  1151→	}
  1152→
  1153→	mode := filemode.Regular
  1154→	if info.Mode()&0o111 != 0 {
  1155→		mode = filemode.Executable
  1156→	}
  1157→
  1158→	content, err := os.ReadFile(filePath) //nolint:gosec // filePath comes from walking the metadata directory
  1159→	if err != nil {
  1160→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to read file: %w", err)
  1161→	}
  1162→
  1163→	// Skip redaction for binary files — they can't contain text secrets and
  1164→	// running string replacement on them would corrupt the data.
  1165→	isBin, binErr := binary.IsBinary(bytes.NewReader(content))
  1166→	if binErr != nil || isBin {
  1167→		hash, err := CreateBlobFromContent(repo, content)
  1168→		if err != nil {
  1169→			return plumbing.ZeroHash, 0, fmt.Errorf("failed to create blob: %w", err)
  1170→		}
  1171→		return hash, mode, nil
  1172→	}
  1173→
  1174→	if strings.HasSuffix(treePath, ".jsonl") {
  1175→		content, err = redact.JSONLBytes(content)
  1176→		if err != nil {
  1177→			return plumbing.ZeroHash, 0, fmt.Errorf("failed to redact secrets: %w", err)
  1178→		}
  1179→	} else {
  1180→		content = redact.Bytes(content)
  1181→	}
  1182→
  1183→	hash, err := CreateBlobFromContent(repo, content)
  1184→	if err != nil {
  1185→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to create blob: %w", err)
  1186→	}
  1187→	return hash, mode, nil
  1188→}
  1189→
  1190→// getGitAuthorFromRepo retrieves the git user.name and user.email from the repository config.
  1191→func getGitAuthorFromRepo(repo *git.Repository) (name, email string) {
  1192→	// Get repository config (includes local settings)
  1193→	cfg, err := repo.Config()
  1194→	if err == nil {
  1195→		name = cfg.User.Name
  1196→		email = cfg.User.Email
  1197→	}
  1198→
  1199→	// Provide sensible defaults if git user is not configured
  1200→	if name == "" {
  1201→		name = "Unknown"
  1202→	}
  1203→	if email == "" {
  1204→		email = "unknown@local"
  1205→	}
  1206→
  1207→	return name, email
  1208→}
  1209→
  1210→// readTranscriptFromTree reads a transcript from a git tree, handling both chunked and non-chunked formats.
  1211→// It checks for chunk files first (.001, .002, etc.), then falls back to the base file.
  1212→// The agentType is used for reassembling chunks in the correct format.
  1213→func readTranscriptFromTree(tree *object.Tree, agentType agent.AgentType) ([]byte, error) {
  1214→	// Collect all transcript-related files
  1215→	var chunkFiles []string
  1216→	var hasBaseFile bool
  1217→
  1218→	for _, entry := range tree.Entries {
  1219→		if entry.Name == paths.TranscriptFileName || entry.Name == paths.TranscriptFileNameLegacy {
  1220→			hasBaseFile = true
  1221→		}
  1222→		// Check for chunk files (full.jsonl.001, full.jsonl.002, etc.)
  1223→		if strings.HasPrefix(entry.Name, paths.TranscriptFileName+".") {
  1224→			idx := agent.ParseChunkIndex(entry.Name, paths.TranscriptFileName)
  1225→			if idx > 0 {
  1226→				chunkFiles = append(chunkFiles, entry.Name)
  1227→			}
  1228→		}
  1229→	}
  1230→
  1231→	// If we have chunk files, read and reassemble them
  1232→	if len(chunkFiles) > 0 {
  1233→		// Sort chunk files by index
  1234→		chunkFiles = agent.SortChunkFiles(chunkFiles, paths.TranscriptFileName)
  1235→
  1236→		// Check if base file should be included as chunk 0.
  1237→		// NOTE: This assumes the chunking convention where the unsuffixed file
  1238→		// (full.jsonl) is chunk 0, and numbered files (.001, .002) are chunks 1+.
  1239→		if hasBaseFile {
  1240→			chunkFiles = append([]string{paths.TranscriptFileName}, chunkFiles...)
  1241→		}
  1242→
  1243→		var chunks [][]byte
  1244→		for _, chunkFile := range chunkFiles {
  1245→			file, err := tree.File(chunkFile)
  1246→			if err != nil {
  1247→				logging.Warn(context.Background(), "failed to read transcript chunk file from tree",
  1248→					slog.String("chunk_file", chunkFile),
  1249→					slog.String("error", err.Error()),
  1250→				)
  1251→				continue
  1252→			}
  1253→			content, err := file.Contents()
  1254→			if err != nil {
  1255→				logging.Warn(context.Background(), "failed to read transcript chunk contents",
  1256→					slog.String("chunk_file", chunkFile),
  1257→					slog.String("error", err.Error()),
  1258→				)
  1259→				continue
  1260→			}
  1261→			chunks = append(chunks, []byte(content))
  1262→		}
  1263→
  1264→		if len(chunks) > 0 {
  1265→			result, err := agent.ReassembleTranscript(chunks, agentType)
  1266→			if err != nil {
  1267→				return nil, fmt.Errorf("failed to reassemble transcript: %w", err)
  1268→			}
  1269→			return result, nil
  1270→		}
  1271→	}
  1272→
  1273→	// Fall back to reading base file (non-chunked or backwards compatibility)
  1274→	if file, err := tree.File(paths.TranscriptFileName); err == nil {
  1275→		if content, err := file.Contents(); err == nil {
  1276→			return []byte(content), nil
  1277→		}
  1278→	}
  1279→
  1280→	// Try legacy filename
  1281→	if file, err := tree.File(paths.TranscriptFileNameLegacy); err == nil {
  1282→		if content, err := file.Contents(); err == nil {
  1283→			return []byte(content), nil
  1284→		}
  1285→	}
  1286→
  1287→	return nil, nil
  1288→}
  1289→
  1290→// Author contains author information for a checkpoint.
  1291→type Author struct {
  1292→	Name  string
  1293→	Email string
  1294→}
  1295→
  1296→// GetCheckpointAuthor retrieves the author of a checkpoint from the entire/checkpoints/v1 commit history.
  1297→// Returns the author of the commit that introduced this checkpoint's metadata.json file.
  1298→// Returns empty Author if the checkpoint is not found or the sessions branch doesn't exist.
  1299→func (s *GitStore) GetCheckpointAuthor(ctx context.Context, checkpointID id.CheckpointID) (Author, error) {
  1300→	_ = ctx // Reserved for future use
  1301→
  1302→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
  1303→	ref, err := s.repo.Reference(refName, true)
  1304→	if err != nil {
  1305→		return Author{}, nil
  1306→	}
  1307→
  1308→	// Path to the checkpoint's metadata file
  1309→	metadataPath := checkpointID.Path() + "/" + paths.MetadataFileName
  1310→
  1311→	// Walk commit history looking for the commit that introduced this file
  1312→	iter, err := s.repo.Log(&git.LogOptions{
  1313→		From:  ref.Hash(),
  1314→		Order: git.LogOrderCommitterTime,
  1315→	})
  1316→	if err != nil {
  1317→		return Author{}, nil
  1318→	}
  1319→	defer iter.Close()
  1320→
  1321→	var author Author
  1322→	var foundCommit *object.Commit
  1323→
  1324→	err = iter.ForEach(func(c *object.Commit) error {
  1325→		tree, treeErr := c.Tree()
  1326→		if treeErr != nil {
  1327→			return nil //nolint:nilerr // Skip commits we can't read, continue searching
  1328→		}
  1329→
  1330→		_, fileErr := tree.File(metadataPath)
  1331→		if fileErr != nil {
  1332→			// File doesn't exist in this commit - we've gone past the creation point
  1333→			if foundCommit != nil {
  1334→				return errStopIteration
  1335→			}
  1336→			return nil
  1337→		}
  1338→
  1339→		// File exists - track it (oldest one with file is the creator)
  1340→		foundCommit = c
  1341→		author = Author{
  1342→			Name:  c.Author.Name,
  1343→			Email: c.Author.Email,
  1344→		}
  1345→		return nil
  1346→	})
  1347→
  1348→	// Ignore errStopIteration - it's just for early exit
  1349→	if err != nil && !errors.Is(err, errStopIteration) {
  1350→		return Author{}, nil
  1351→	}
  1352→
  1353→	return author, nil
  1354→}
