+	if existingContent != "" {
+		combined = existingContent + "\n\n---\n\n" + newContent
+	} else {
+		combined = newContent
+	}
+
+	// Write combined prompts blob
+	blobHash, err := CreateBlobFromContent(s.repo, []byte(combined))
+	if err != nil {
+		return fmt.Errorf("failed to create prompt blob: %w", err)
+	}
