	if len(decoded.TurnCheckpointIDs) != 2 {
		t.Errorf("expected 2 IDs, got %d", len(decoded.TurnCheckpointIDs))
	}

	// Test nil serialization (omitempty)
	empty := stateSnippet{}
	data, _ = json.Marshal(empty)
	if string(data) != "{}" {
		t.Errorf("expected empty JSON, got %s", string(data))
	}
