  1170→// ensureSessionsBranch ensures the entire/checkpoints/v1 branch exists.
  1171→func (s *GitStore) ensureSessionsBranch() error {
  1172→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
  1173→	_, err := s.repo.Reference(refName, true)
