  1197→// getSessionsBranchTree returns the tree object for the entire/checkpoints/v1 branch.
  1198→// Falls back to origin/entire/checkpoints/v1 if the local branch doesn't exist.
  1199→func (s *GitStore) getSessionsBranchTree() (*object.Tree, error) {
