  1224→// CreateBlobFromContent creates a blob object from in-memory content.
  1225→// Exported for use by strategy package (session_test.go)
  1226→func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
  1227→	obj := repo.Storer.NewEncodedObject()
  1228→	obj.SetType(plumbing.BlobObject)
  1229→	obj.SetSize(int64(len(content)))
  1230→
  1231→	writer, err := obj.Writer()
  1232→	if err != nil {
  1233→		return plumbing.ZeroHash, fmt.Errorf("failed to get object writer: %w", err)
  1234→	}
  1235→
  1236→	_, err = writer.Write(content)
  1237→	if err != nil {
  1238→		_ = writer.Close()
  1239→		return plumbing.ZeroHash, fmt.Errorf("failed to write blob content: %w", err)
  1240→	}
  1241→	if err := writer.Close(); err != nil {
  1242→		return plumbing.ZeroHash, fmt.Errorf("failed to close blob writer: %w", err)
  1243→	}
  1244→
  1245→	hash, err := repo.Storer.SetEncodedObject(obj)
  1246→	if err != nil {
  1247→		return plumbing.ZeroHash, fmt.Errorf("failed to store blob object: %w", err)
  1248→	}
  1249→	return hash, nil
  1250→}
