  1252→// copyMetadataDir copies all files from a directory to the checkpoint path.
  1253→// Used to include additional metadata files like task checkpoints, subagent transcripts, etc.
  1254→func (s *GitStore) copyMetadataDir(metadataDir, basePath string, entries map[string]object.TreeEntry) error {
  1255→	err := filepath.Walk(metadataDir, func(path string, info os.FileInfo, err error) error {
  1256→		if err != nil {
  1257→			return err
  1258→		}
  1259→		if info.IsDir() {
  1260→			return nil
  1261→		}
  1262→
  1263→		// Skip symlinks to prevent reading files outside the metadata directory.
  1264→		// A symlink could point to sensitive files (e.g., /etc/passwd) which would
  1265→		// then be captured in the checkpoint and stored in git history.
  1266→		if info.Mode()&os.ModeSymlink != 0 {
  1267→			return nil
  1268→		}
  1269→
  1270→		// Get relative path within metadata dir
  1271→		relPath, err := filepath.Rel(metadataDir, path)
  1272→		if err != nil {
  1273→			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
  1274→		}
  1275→
  1276→		// Prevent path traversal via symlinks pointing outside the metadata dir
  1277→		if strings.HasPrefix(relPath, "..") {
  1278→			return fmt.Errorf("path traversal detected: %s", relPath)
  1279→		}
  1280→
  1281→		// Create blob from file with secrets redaction
  1282→		blobHash, mode, err := createRedactedBlobFromFile(s.repo, path, relPath)
  1283→		if err != nil {
  1284→			return fmt.Errorf("failed to create blob for %s: %w", path, err)
  1285→		}
  1286→
  1287→		// Store at checkpoint path
  1288→		fullPath := basePath + relPath
  1289→		entries[fullPath] = object.TreeEntry{
  1290→			Name: fullPath,
  1291→			Mode: mode,
  1292→			Hash: blobHash,
  1293→		}
  1294→
  1295→		return nil
  1296→	})
  1297→	if err != nil {
  1298→		return fmt.Errorf("failed to walk metadata directory: %w", err)
  1299→	}
  1300→	return nil
  1301→}
