  1303→// createRedactedBlobFromFile reads a file, applies secrets redaction, and creates a git blob.
  1304→// JSONL files get JSONL-aware redaction; all other files get plain string redaction.
  1305→func createRedactedBlobFromFile(repo *git.Repository, filePath, treePath string) (plumbing.Hash, filemode.FileMode, error) {
  1306→	info, err := os.Stat(filePath)
  1307→	if err != nil {
  1308→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to stat file: %w", err)
  1309→	}
  1310→
  1311→	mode := filemode.Regular
  1312→	if info.Mode()&0o111 != 0 {
  1313→		mode = filemode.Executable
  1314→	}
  1315→
  1316→	content, err := os.ReadFile(filePath) //nolint:gosec // filePath comes from walking the metadata directory
  1317→	if err != nil {
  1318→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to read file: %w", err)
  1319→	}
  1320→
  1321→	// Skip redaction for binary files — they can't contain text secrets and
  1322→	// running string replacement on them would corrupt the data.
  1323→	isBin, binErr := binary.IsBinary(bytes.NewReader(content))
  1324→	if binErr != nil || isBin {
  1325→		hash, err := CreateBlobFromContent(repo, content)
  1326→		if err != nil {
  1327→			return plumbing.ZeroHash, 0, fmt.Errorf("failed to create blob: %w", err)
  1328→		}
  1329→		return hash, mode, nil
  1330→	}
  1331→
  1332→	if strings.HasSuffix(treePath, ".jsonl") {
  1333→		content, err = redact.JSONLBytes(content)
  1334→		if err != nil {
  1335→			return plumbing.ZeroHash, 0, fmt.Errorf("failed to redact secrets: %w", err)
  1336→		}
  1337→	} else {
  1338→		content = redact.Bytes(content)
  1339→	}
  1340→
  1341→	hash, err := CreateBlobFromContent(repo, content)
  1342→	if err != nil {
  1343→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to create blob: %w", err)
  1344→	}
  1345→	return hash, mode, nil
  1346→}
