  1454→// GetCheckpointAuthor retrieves the author of a checkpoint from the entire/checkpoints/v1 commit history.
  1455→// Returns the author of the commit that introduced this checkpoint's metadata.json file.
  1456→// Returns empty Author if the checkpoint is not found or the sessions branch doesn't exist.
  1457→func (s *GitStore) GetCheckpointAuthor(ctx context.Context, checkpointID id.CheckpointID) (Author, error) {
  1458→	_ = ctx // Reserved for future use
  1459→
  1460→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
  1461→	ref, err := s.repo.Reference(refName, true)
  1462→	if err != nil {
  1463→		return Author{}, nil
  1464→	}
  1465→
  1466→	// Path to the checkpoint's metadata file
  1467→	metadataPath := checkpointID.Path() + "/" + paths.MetadataFileName
  1468→
  1469→	// Walk commit history looking for the commit that introduced this file
  1470→	iter, err := s.repo.Log(&git.LogOptions{
  1471→		From:  ref.Hash(),
  1472→		Order: git.LogOrderCommitterTime,
  1473→	})
  1474→	if err != nil {
  1475→		return Author{}, nil
  1476→	}
  1477→	defer iter.Close()
  1478→
  1479→	var author Author
  1480→	var foundCommit *object.Commit
  1481→
  1482→	err = iter.ForEach(func(c *object.Commit) error {
  1483→		tree, treeErr := c.Tree()
  1484→		if treeErr != nil {
  1485→			return nil //nolint:nilerr // Skip commits we can't read, continue searching
  1486→		}
  1487→
  1488→		_, fileErr := tree.File(metadataPath)
  1489→		if fileErr != nil {
  1490→			// File doesn't exist in this commit - we've gone past the creation point
  1491→			if foundCommit != nil {
  1492→				return errStopIteration
  1493→			}
  1494→			return nil
  1495→		}
  1496→
  1497→		// File exists - track it (oldest one with file is the creator)
  1498→		foundCommit = c
  1499→		author = Author{
  1500→			Name:  c.Author.Name,
  1501→			Email: c.Author.Email,
  1502→		}
  1503→		return nil
  1504→	})
  1505→
  1506→	// Ignore errStopIteration - it's just for early exit
  1507→	if err != nil && !errors.Is(err, errStopIteration) {
  1508→		return Author{}, nil
  1509→	}
  1510→
  1511→	return author, nil
  1512→}
