// transitionSessionTurnEnd fires EventTurnEnd to move the session from
// ACTIVE → IDLE. Best-effort: logs warnings on failure rather than
// returning errors.
func transitionSessionTurnEnd(sessionID string) {
	turnState, loadErr := strategy.LoadSessionState(sessionID)
	if loadErr != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to load session state for turn end: %v\n", loadErr)
		return
	}
	if turnState == nil {
		return
	}
	remaining := strategy.TransitionAndLog(turnState, session.EventTurnEnd, session.TransitionContext{})

	// Dispatch strategy-specific actions if any remain after common handling
	if len(remaining) > 0 {
		strat := GetStrategy()
		if handler, ok := strat.(strategy.TurnEndHandler); ok {
			if err := handler.HandleTurnEnd(turnState, remaining); err != nil {
				fmt.Fprintf(os.Stderr, "Warning: turn-end action dispatch failed: %v\n", err)
			}
		}
	}

	if updateErr := strategy.SaveSessionState(turnState); updateErr != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to update session phase on turn end: %v\n", updateErr)
	}
}

// markSessionEnded transitions the session to ENDED phase via the state machine.
func markSessionEnded(sessionID string) error {
	state, err := strategy.LoadSessionState(sessionID)
	if err != nil {
		return fmt.Errorf("failed to load session state: %w", err)
	}
	if state == nil {
		return nil // No state file, nothing to update
	}

	strategy.TransitionAndLog(state, session.EventSessionStop, session.TransitionContext{})

	now := time.Now()
	state.EndedAt = &now

	if err := strategy.SaveSessionState(state); err != nil {
		return fmt.Errorf("failed to save session state: %w", err)
	}

// condenseAndUpdateState runs condensation for a session and updates state afterward.
// Returns true if condensation succeeded.
func (s *ManualCommitStrategy) condenseAndUpdateState(
	logCtx context.Context,
	repo *git.Repository,
	checkpointID id.CheckpointID,
	state *SessionState,
	head *plumbing.Reference,
	shadowBranchName string,
	shadowBranchesToDelete map[string]struct{},
) {
	result, err := s.CondenseSession(repo, checkpointID, state)
	if err != nil {
		fmt.Fprintf(os.Stderr, "[entire] Warning: condensation failed for session %s: %v\n",
			state.SessionID, err)
		logging.Warn(logCtx, "post-commit: condensation failed",
			slog.String("session_id", state.SessionID),
			slog.String("error", err.Error()),
		)
		return
	}

	// Track this shadow branch for cleanup
	shadowBranchesToDelete[shadowBranchName] = struct{}{}

	// Update session state for the new base commit
	newHead := head.Hash().String()
	state.BaseCommit = newHead
	state.AttributionBaseCommit = newHead
	state.StepCount = 0
	state.CheckpointTranscriptStart = result.TotalTranscriptLines

	// Clear attribution tracking — condensation already used these values
	state.PromptAttributions = nil
	state.PendingPromptAttribution = nil
	state.FilesTouched = nil

	// Save checkpoint ID so subsequent commits can reuse it (e.g., amend restores trailer)
	state.LastCheckpointID = checkpointID

	shortID := state.SessionID
	if len(shortID) > 8 {
		shortID = shortID[:8]
	}
	fmt.Fprintf(os.Stderr, "[entire] Condensed session %s: %s (%d checkpoints)\n",
		shortID, result.CheckpointID, result.CheckpointsCount)

	logging.Info(logCtx, "session condensed",
		slog.String("strategy", "manual-commit"),
		slog.String("checkpoint_id", result.CheckpointID.String()),
		slog.Int("checkpoints_condensed", result.CheckpointsCount),
		slog.Int("transcript_lines", result.TotalTranscriptLines),
	)
}

