		t.Fatalf("SimulateStop failed: %v", err)
	}

	// Create file B manually (not through session)
	env.WriteFile("fileB.go", "package main\n\nfunc B() {}\n")

	// Commit both files together - should get checkpoint (partial overlap is enough)
