		return ""
	}

	commit, err := repo.CommitObject(ref.Hash())
	if err != nil {
		return ""
	}

	// Extract checkpoint ID from commit message
	// Format: "Checkpoint: <12-hex-char-id>\n\nSession: ...\nStrategy: ..."
	for _, line := range strings.Split(commit.Message, "\n") {
