// Uses checkpoint.GitStore.ReadCommitted() for reading from entire/checkpoints/v1.
func (s *ManualCommitStrategy) getCheckpointLog(checkpointID id.CheckpointID) ([]byte, error) {
	store, err := s.getCheckpointStore()
