		// Simulate human at terminal: ENTIRE_TEST_TTY=1 makes hasTTY() return true
		// and askConfirmTTY() return defaultYes without reading from /dev/tty.
		prepCmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=1")
